package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;

/** B5 plan verification contract, including the explicit closed-gate branch. */
public class AgentPlanB5Test extends TestCase {
    private ObjectNode snapshot(){return (ObjectNode)parse("{\"sheets\":{\"s\":{\"name\":\"Orders\",\"rowCount\":10,\"columnCount\":10,\"defaultRowHeight\":24,\"cellData\":{\"0\":{\"0\":{\"v\":\"keep\"}}},\"rowData\":{\"0\":{\"h\":24}},\"columnData\":{\"0\":{\"w\":80}},\"mergeData\":[]}}}");}
    private ObjectNode action(String type){ObjectNode a=obj().put("schemaVersion","2.0").put("type",type);ObjectNode target=obj().put("sheetId","s");if("setStyle".equals(type)){target.put("range","A1");a.put("background","#112233");}else if("setRowHeight".equals(type))a.put("rowPosition",1).put("height",50);else a.put("columnPosition",1).put("width",120);a.set("target",target);return a;}
    private String range(String type){return "setStyle".equals(type)?"A1":"setRowHeight".equals(type)?"A1:J1":"A1:A10";}
    private ArrayNode scopes(String type){return arr().add(obj().put("sheetId","s").put("range",range(type)));}
    private ObjectNode plan(String type){ObjectNode write=obj().put("stepId","W").put("tool","apply_actions").put("executionMode","fixed").put("objective","format");write.set("dependsOn",arr());write.set("verificationRules",arr().add(obj().put("type","tool_success")));write.set("inputBindings",obj().put("overwrite","confirmed").set("actions",arr().add(action(type))));
        ObjectNode verify=obj().put("stepId","V").put("tool","verify_result").put("executionMode","fixed").put("objective","verify");verify.set("dependsOn",arr().add("W"));verify.set("verificationRules",arr().add(obj().put("type","tool_success")));verify.set("inputBindings",obj().put("sheetId","s").put("range",range(type)).put("kind","matches_format").set("write",obj().put("$step","W")));
        ObjectNode p=obj();p.set("steps",arr().add(write).add(verify));p.set("acceptanceCriteria",arr().add(obj().put("type","step_succeeded").put("stepId","W")).add(obj().put("type","step_succeeded").put("stepId","V")));return p;}
    private void reject(Runnable action){try{action.run();fail("unsafe format plan accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    private void admit(ObjectNode p,String type,boolean gate){AgentPlan.validateForRun(p,snapshot(),scopes(type),"s",true,true,gate);}
    public void testCandidatePlanPromptMatchesGateAndVerifier(){String closed=AgentPlan.contract(false),candidate=AgentPlan.contract(true);assertEquals(AgentPlan.CONTRACT,closed);assertTrue(closed.contains("样式、筛选和结构写入不支持"));assertTrue(candidate.contains("matches_format"));assertTrue(candidate.contains("setStyle"));assertTrue(candidate.contains("setRowHeight"));assertTrue(candidate.contains("setColumnWidth"));assertFalse(candidate.contains("样式、筛选和结构写入不支持"));}
    public void testCandidatePromptShowsRequiredV2FormatAction(){String candidate=AgentPlan.contract(true);assertTrue(candidate.contains("\"schemaVersion\":\"2.0\""));assertTrue(candidate.contains("\"type\":\"setStyle\""));assertTrue(candidate.contains("\"target\":{\"sheetId\":\"s\",\"range\":\"A1\"}"));assertTrue(candidate.contains("\"kind\":\"matches_format\""));}
    public void testAllThreeFormatsRequireGateAndExactVerifier(){for(String type:new String[]{"setStyle","setRowHeight","setColumnWidth"}){ObjectNode p=plan(type);reject(()->admit(p,type,false));admit(p,type,true);
        ObjectNode verify=(ObjectNode)p.path("steps").get(1).path("inputBindings");verify.put("kind","non_empty");reject(()->admit(p,type,true));verify.put("kind","matches_format");verify.put("range","A1");if(!"setStyle".equals(type))reject(()->admit(p,type,true));}}
    public void testBadFormatActionRejectedDuringWholePlanPreflight(){ObjectNode p=plan("setStyle"),a=(ObjectNode)p.path("steps").get(0).path("inputBindings").path("actions").get(0);a.put("fontWeight","bold");reject(()->admit(p,"setStyle",true));a.remove("fontWeight");a.put("background","red");reject(()->admit(p,"setStyle",true));}
    public void testSavedFormatVerifierChecksSnapshotAndReceiptEvidence(){for(String type:new String[]{"setStyle","setRowHeight","setColumnWidth"}){ObjectNode source=snapshot(),manifest=WriteManifest.previewB5Format(source,action(type),scopes(type)),saved=WriteManifest.applyB5Format(source,manifest);ObjectNode change=obj().put("kind","controlled-format").put("operationId","call").put("afterHash",hash(saved));change.set("formatPatch",manifest.path("patch"));ObjectNode write=obj().put("transportVersion",2).put("callId","call").put("validation","PASSED").put("persistenceStatus","SAVED").put("loadedRevision",hash(saved)).put("sourceRevision",hash(saved));write.set("executedChange",change);ObjectNode args=obj().put("sheetId","s").put("range",range(type)).put("kind","matches_format");args.set("write",write);
        assertTrue(AgentTools.verify(saved,args).path("passed").asBoolean());ObjectNode wrong=saved.deepCopy();if("setStyle".equals(type))((ObjectNode)wrong.path("sheets").path("s").path("cellData").path("0").path("0").path("s").path("bg")).put("rgb","#ffffff");else ((ObjectNode)wrong.path("sheets").path("s").path("setRowHeight".equals(type)?"rowData":"columnData").path("0")).put("setRowHeight".equals(type)?"h":"w",999);reject(()->AgentTools.verify(wrong,args));
        write.put("persistenceStatus","NOT_SAVED");reject(()->AgentTools.verify(saved,args));write.put("persistenceStatus","SAVED");change.put("afterHash","forged");reject(()->AgentTools.verify(saved,args));}}
}
